const makeElement = id => ({ id, style:{}, hidden:false, disabled:false, textContent:'', width:0, height:0, addEventListener:noop, setAttribute:noop, focus:noop, setPointerCapture:noop, getContext:()=>ctx, getBoundingClientRect:()=>({width:1000,height:620}), closest:()=>null });
